using R1 = std::ratio<6, 9>;       // Internal reduction to 2/3
using R2 = std::ratio<1, 6>;

// Compile-time Addition: 2/3 + 1/6 = 5/6
using R_Sum = std::ratio_add<R1, R2>;

static_assert(R_Sum::num == 5);
static_assert(R_Sum::den == 6);

// Compile-time Multiplication: 2/3 * 1/6 = 2/18 = 1/9
using R_Prod = std::ratio_multiply<R1, R2>;

constexpr long long N = R_Prod::num;
constexpr long long D = R_Prod::den;

static_assert(N == 1);
static_assert(D == 9);
